import{_ as t,o as s,c as i,a3 as l,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const u="/bilder/sekundarstufen/gruppenprozesse-zp10-teilleistungen-art.png",o="/bilder/sekundarstufen/gruppenprozesse-zp10-teilleistungen-zuordnen.png",k=JSON.parse('{"title":"ZP10-Prüfungsnoten aus Teilleistungen übernehmen","description":"","frontmatter":{"title":"ZP10-Prüfungsnoten aus Teilleistungen übernehmen","source_pageid":1159,"source_revision":3919},"headers":[],"relativePath":"zeugnisse/sekundarstufen/pruefungsnoten-aus-teilleistungen-holen-gruppenprozesse-zentrale-klausuren.md","filePath":"zeugnisse/sekundarstufen/pruefungsnoten-aus-teilleistungen-holen-gruppenprozesse-zentrale-klausuren.md"}'),a={name:"zeugnisse/sekundarstufen/pruefungsnoten-aus-teilleistungen-holen-gruppenprozesse-zentrale-klausuren.md"};function d(g,r,p,h,c,m){return s(),i("div",null,[...r[0]||(r[0]=[l('<h1 id="zp10-prufungsnoten-aus-teilleistungen-ubernehmen" tabindex="-1">ZP10-Prüfungsnoten aus Teilleistungen übernehmen <a class="header-anchor" href="#zp10-prufungsnoten-aus-teilleistungen-ubernehmen" aria-label="Permalink to &quot;ZP10-Prüfungsnoten aus Teilleistungen übernehmen&quot;">​</a></h1><p>Ordnen Sie vorhandene Teilleistungen den Notenarten im Bereich ZP10/ZK zu und übernehmen Sie die Werte.</p><p><a href="/bilder/sekundarstufen/gruppenprozesse-zp10-teilleistungen-art.png"><img src="'+u+'" alt="Holen der Teilleistungen." loading="lazy"></a></p><p><em>Holen der Teilleistungen.</em></p><p>Wenn die ZP-/ZK-Noten als Teilleistungen im <strong>aktuellen Halbjahr</strong> erfasst sind, können Sie sie nach <strong>Schüler → ZP 10/ZK</strong> übernehmen. Der Prozess ordnet <strong>Vornote</strong>, <strong>schriftliche Note</strong> und <strong>Abschlussnote</strong> den entsprechenden Spalten zu.</p><p>Die Noten können direkt in SchILD-NRW eingetragen werden. Die Notenerfassung mit GradeHub und WeNoM ist dem SVWS-Server zugeordnet. Einrichtung und Bedienung sind in der <a href="https://doku.svws-nrw.de/" target="_blank" rel="noreferrer">SVWS-Dokumentation</a> beschrieben; siehe auch <a href="/zeugnisse/noteneingabe.html">Noten mit GradeHub und WeNoM erfassen</a>.</p><p>Im Fenster, dass sich nach dem Anklicken des Gruppenprozesses öffnet, ist zuerst auszuwählen, um welche <em>ZP 10/ZK-Teilleistung</em> es sich handelt.</p><p>Dieses Feld heißt <strong>Notenart</strong> und sein Feld bestimmt, in welcher <em>Spalte</em> die gleich geholte Note eingetragen werden wird.</p><p><a href="/bilder/sekundarstufen/gruppenprozesse-zp10-teilleistungen-zuordnen.png"><img src="'+o+'" alt="Zuordnen der ZP-10/ZK-Noten zu einer der Teilleistungen." loading="lazy"></a></p><p><em>Zuordnen der ZP-10/ZK-Noten zu einer der Teilleistungen.</em></p><p>Nachdem die <em>Notenart</em> oben gewählt wurde, ist nun die konkret den Schülern gegebene Teilleistung dieser Notenart zuzuordnen. Dies wird über das Feld <strong>Zugehörige Teilleistung</strong> vorgenommen.</p><p>Die Teilleistungen der Schule können vom Namen der beliebig gewählt werden, daher ist hier diese Zuordnung manuell vorzunehmen.</p><p>Hier im Beispiel entspricht die ZP-10-Note <em>Schriftliche Note</em> der eindeutig gewählten Bezeichnung <em>&quot;ZP 10 Schriftliche Note&quot;</em>.</p>',13),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,[n("Hier ist es technisch möglich, falsche Zuordnungen vorzunehmen, also zum Beispiel die "),e("em",null,"Vornoten"),n(" als die "),e("em",null,"schriftlichen Noten"),n(" der Prüfung oder direkt als die "),e("em",null,"Abschlussnoten"),n(" zu importieren.")])],-1),e("p",null,[n("Es kann der Haken bei "),e("strong",null,"Vorhandene Noten überschreiben"),n(" gesetzt werden, um schon vorgenommene Änderungen bei individuellen Schülern mit den original eingetragenen Teilleistungen zu überschreiben.")],-1),e("p",null,[n("Klicken Sie auf "),e("code",null,"Noten holen"),n(", um den Gruppenprozess zu starten..")],-1),e("div",{"data-hint-kind":"right",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"right","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"m8 12 3 3 5-6"})]),n("Richtig – Fertig")]),e("p",null,"Dieser Vorgang ist für alle im konkreten Prozess der Schule verwendeten Teilleistungen zu wiederholen."),e("p",null,"Dann ist diese Vorbereitung abgeschlossen.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Pr%C3%BCfungsnoten_aus_Teilleistungen_holen_(Gruppenprozesse_Zentrale_Klausuren)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 3919.")],-1)])])}const z=t(a,[["render",d]]);export{k as __pageData,z as default};
